type Par = ReturnType<typeof p>
const ins = (l: AccLesson, after: string, ...ps: Par[]) => {
  const arr = l.content.paragraphs
  const i = arr.findIndex(x => x.id === after)
  arr.splice(i < 0 ? Math.max(arr.length - 1, 0) : i + 1, 0, ...ps)
}
